-- =============================================================
-- online_store_full: the shop's complete records, 2023 to 2024
-- Databases & SQL for Analysts (from Day 10)
--
-- Exported from the shop's real systems, so it is big and messy
-- on purpose. Do not clean it here: finding and fixing the mess
-- is what Days 10 and 11 are about.
--
-- Run the whole file once (it takes about a minute):
--   mysql -u root -p < online_store_full.sql
-- or in MySQL Workbench: File > Run SQL Script...
--
-- Needs MySQL 8.0 or newer. This file deletes and rebuilds the
-- online_store_full database. It does not touch online_store.
-- =============================================================

SET NAMES utf8mb4;   -- read this file as UTF-8, so names like Zoë and José load correctly

DROP DATABASE IF EXISTS online_store_full;
CREATE DATABASE online_store_full CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE online_store_full;

CREATE TABLE categories (
    category_id   INT          AUTO_INCREMENT,
    category_name VARCHAR(50)  NOT NULL,
    PRIMARY KEY (category_id)
);

CREATE TABLE products (
    product_id     INT           AUTO_INCREMENT,
    product_name   VARCHAR(100)  NOT NULL,
    category_id    INT,
    price          DECIMAL(10,2) NOT NULL,
    cost_price     DECIMAL(10,2),
    stock_quantity INT           NOT NULL DEFAULT 0,
    launch_date    DATE,
    is_active      BOOLEAN       NOT NULL DEFAULT TRUE,
    PRIMARY KEY (product_id),
    FOREIGN KEY (category_id) REFERENCES categories(category_id)
);

CREATE TABLE customers (
    customer_id         INT          AUTO_INCREMENT,
    first_name          VARCHAR(50)  NOT NULL,
    last_name           VARCHAR(50),
    email               VARCHAR(100) NOT NULL,
    phone               VARCHAR(25),
    city                VARCHAR(50),
    country             VARCHAR(50),
    signup_date         VARCHAR(20),
    acquisition_channel VARCHAR(30),
    PRIMARY KEY (customer_id)
);

CREATE TABLE employees (
    employee_id INT           AUTO_INCREMENT,
    first_name  VARCHAR(50)   NOT NULL,
    last_name   VARCHAR(50)   NOT NULL,
    email       VARCHAR(100)  NOT NULL,
    department  VARCHAR(50)   NOT NULL,
    job_title   VARCHAR(100)  NOT NULL,
    manager_id  INT,
    hire_date   DATE          NOT NULL,
    salary      DECIMAL(12,2) NOT NULL,
    city        VARCHAR(50),
    PRIMARY KEY (employee_id),
    FOREIGN KEY (manager_id) REFERENCES employees(employee_id)
);

CREATE TABLE orders (
    order_id     INT          AUTO_INCREMENT,
    customer_id  INT          NOT NULL,
    order_date   DATETIME     NOT NULL,
    status       VARCHAR(20),
    channel      VARCHAR(10),
    coupon_code  VARCHAR(20),
    shipping_fee DECIMAL(8,2) NOT NULL DEFAULT 0,
    PRIMARY KEY (order_id),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE order_items (
    order_item_id INT           AUTO_INCREMENT,
    order_id      INT           NOT NULL,
    product_id    INT           NOT NULL,
    quantity      INT           NOT NULL,
    unit_price    DECIMAL(10,2) NOT NULL,
    PRIMARY KEY (order_item_id),
    FOREIGN KEY (order_id)   REFERENCES orders(order_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);

CREATE TABLE payments (
    payment_id     INT           AUTO_INCREMENT,
    order_id       INT           NOT NULL,
    payment_date   DATETIME      NOT NULL,
    payment_method VARCHAR(30),
    amount         DECIMAL(10,2) NOT NULL,
    payment_status VARCHAR(20)   NOT NULL,
    PRIMARY KEY (payment_id),
    FOREIGN KEY (order_id) REFERENCES orders(order_id)
);

CREATE TABLE returns (
    return_id     INT           AUTO_INCREMENT,
    order_item_id INT           NOT NULL,
    return_date   DATE          NOT NULL,
    reason        VARCHAR(100),
    refund_amount DECIMAL(10,2) NOT NULL,
    processed_by  INT,
    PRIMARY KEY (return_id),
    FOREIGN KEY (order_item_id) REFERENCES order_items(order_item_id),
    FOREIGN KEY (processed_by)  REFERENCES employees(employee_id)
);

CREATE TABLE reviews (
    review_id   INT      AUTO_INCREMENT,
    product_id  INT      NOT NULL,
    customer_id INT      NOT NULL,
    rating      TINYINT,
    review_text TEXT,
    review_date DATE     NOT NULL,
    PRIMARY KEY (review_id),
    FOREIGN KEY (product_id)  REFERENCES products(product_id),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

-- Website tracking data comes from a separate analytics tool,
-- so it has no foreign keys to the shop's tables.
CREATE TABLE web_events (
    event_id       BIGINT       AUTO_INCREMENT,
    session_id     VARCHAR(20)  NOT NULL,
    customer_id    INT,
    event_time     DATETIME     NOT NULL,
    event_type     VARCHAR(30)  NOT NULL,
    product_id     INT,
    order_id       INT,
    device         VARCHAR(20),
    traffic_source VARCHAR(30),
    PRIMARY KEY (event_id)
);


-- categories: 5 rows
START TRANSACTION;
COMMIT;

